def mostFrequent (xs : List Int) (h_precond : mostFrequent_precond (xs)) : Int :=
  let count := fun x => xs.countP (fun y => y = x)
  let maxCount := xs.foldl (fun acc x => max acc (count x)) 0
  xs.foldl (fun acc x => if count x = maxCount then x else acc) (xs.head!)
